def pins_for(shape) -> dict[int, str]:
    """The current cuBLASLt version's exact-row pins of (N, K) (rows -> descriptor
    hex): EXACT_PINS over PINS."""
    shape = tuple(shape)
    out = dict(PINS.get(version(), {}).get(shape, {}))
    out.update(
        {r: h for r, (_, h) in EXACT_PINS.get(version(), {}).get(shape, {}).items()}
    )
    keep = default_rows(shape)
    return {r: h for r, h in out.items() if r not in keep}


def default_rows(shape) -> frozenset:
    """Rows of (N, K) where the measured best is F.linear's default (DEFAULT_ROWS)."""
    return DEFAULT_ROWS.get(version(), {}).get(tuple(shape), frozenset())


class PinnedLinear:
    """``weight`` [N, K] BF16 on pinned algorithms for the rows in ``pins`` that pass
    the algorithm check here: ``kernels`` (served rows), ``run(x, out)``."""

    def __init__(self, weight: torch.Tensor, pins: dict[int, str]):
        mod = _module()
        self.weight = weight
        self.kernels: dict[int, torch.Tensor] = {}
        self.rejected: list[int] = []
        need = 0
        for rows, hexstr in sorted(pins.items()):
            algo = _algo(hexstr)
            probe = torch.empty(
                (rows, weight.shape[1]), dtype=weight.dtype, device=weight.device
            )
            size = int(mod.lt_check(probe, weight, algo))
            if size < 0:
                self.rejected.append(rows)
                continue
            self.kernels[rows] = algo
            need = max(need, size)
        self.workspace = torch.empty(
            max(need, 1), dtype=torch.uint8, device=weight.device
        )

    def takes(self, x: torch.Tensor) -> bool:
        return (
            x.dim() == 2
            and x.shape[0] in self.kernels
            and x.stride(1) == 1
            and x.dtype == self.weight.dtype
        )

    def run(self, x: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        _module().lt_gemm(out, x, self.weight, self.kernels[x.shape[0]], self.workspace)
        return out


def bin_pin(shape, rows: int) -> "tuple[int, int, str, str] | None":
    """The BIN_PINS bin (lo, hi, label, descriptor) of (N, K) covering ``rows``."""
    if rows in default_rows(shape):
        return None
    for lo, hi, label, hexstr in BIN_PINS.get(version(), {}).get(tuple(shape), ()):
        if lo <= rows <= hi:
            return lo, hi, label, hexstr
    return None


def pin_labels(shape, rows) -> dict[int, str]:
    """Rows -> 'pinned cuBLASLt <algo> (row bin lo-hi | exact row)' for the rows of
    ``rows`` a pin of (N, K) ``shape`` covers (the coverage log's names)."""
    shape = tuple(shape)
    table, out = pins_for(shape), {}
    exact = EXACT_PINS.get(version(), {}).get(shape, {})
    keep = default_rows(shape)
    for r in rows:
        if r in keep:
            out[r] = "measured cuBLAS default (no pinned algorithm beats it)"
        elif r in exact:
            out[r] = f"pinned cuBLASLt {exact[r][0]} (exact row)"
        elif r in table:
            out[r] = "pinned cuBLASLt (exact row)"
        elif (b := bin_pin(shape, r)) is not None:
            out[r] = f"pinned cuBLASLt {b[2]} (row bin {b[0]}-{b[1]})"
    return out


def pinned(
    weight: torch.Tensor, rows, strict: bool = False
) -> "PinnedLinear | None":
    """A ``PinnedLinear`` of ``weight`` for those of ``rows`` with a pin (or None):
    the exact-row PINS first, then the BIN_PINS bin. ``strict`` (NQ-NOFALLBACK
    deployments): a pin the algorithm check rejects raises instead of leaving the
    row on F.linear."""
    table = pins_for(weight.shape)
    if strict and not table and not BIN_PINS.get(version(), {}).get(tuple(weight.shape)):
        searched = sorted(
            {
                v
                for v, t in (*PINS.items(), *BIN_PINS.items(), *EXACT_PINS.items())
                if tuple(weight.shape) in t
            }
        )
        if searched:
            from .shapes import refuse

            refuse(
                "pinned cuBLASLt draft linear",
                f"(N, K) {tuple(weight.shape)}: pins were searched with cuBLASLt "
                f"{searched}, the loaded one is {version()} (algorithm IDs are not "
                "portable across versions; re-run the search for this image)",
            )
    pins = {}
    for r in rows:
        if r in table:
            pins[r] = table[r]
        elif (b := bin_pin(weight.shape, r)) is not None:
            pins[r] = b[3]
    if not pins:
        return None
    linear = PinnedLinear(weight, pins)
    if linear.rejected:
        if strict:
            from .shapes import refuse

            refuse(
                "pinned cuBLASLt draft linear",
                f"(N, K) {tuple(weight.shape)}: the algorithm check rejects the pins "
                f"at rows {linear.rejected}",
            )
        logger.warning_once(
            "Kimi K3 sdec: cuBLASLt pins of (N, K) %s rejected by the algorithm "
            "check at rows %s (they run F.linear)",
            tuple(weight.shape),
            linear.rejected,
        )
    return linear if linear.kernels else None


class WithPins:
    """A prepared projection (``kernels`` / ``run(x, out)`` / ``policies``, or
    None) plus a ``PinnedLinear`` for rows it does not serve."""

    def __init__(self, prepared, pins: PinnedLinear):
        self.prepared, self.pins = prepared, pins
        self.policies = prepared.policies if prepared is not None else {}
        self.kernels = dict(pins.kernels)
        if prepared is not None:
            self.kernels.update(prepared.kernels)

    def run(self, x: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        if self.prepared is not None and x.shape[0] in self.prepared.kernels:
            return self.prepared.run(x, out)
        return self.pins.run(x, out)


def with_pins(prepared, weight: torch.Tensor, rows, strict: bool = False):
    """``prepared`` (a split-K projection of ``weight`` or None) extended by the
    pins of the ``rows`` it does not serve."""
    served = set(prepared.kernels) if prepared is not None else set()
    pins = pinned(weight, [r for r in rows if r not in served], strict)
    return prepared if pins is None else WithPins(prepared, pins)
